INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('diebesgut-wien-favoriten-kellerabteil-e-scooter-akkus','Diebesgut in Wien-Favoriten: 100 Akkus in fremdem Kellerabteil','Ein Mieter in Wien-Favoriten fand in seinem Kellerabteil fremde E-Scooter, Fahrräder und rund 100 Akkus. Ein 45-jähriger Hausbewohner wurde angezeigt.','Mutmaßliches **Diebesgut in Wien-Favoriten** ist in einem fremden Kellerabteil eines Wohnhauses aufgetaucht: Ein Bewohner entdeckte dort E-Scooter, Fahrräder, Elektrogeräte und rund 100 Akkus, die ihm nicht gehörten. Die Landespolizeidirektion Wien hat den Fund am Freitag öffentlich gemacht, ein Hausbewohner wurde angezeigt.

## Fehlendes Vorhängeschloss brachte den Fall ins Rollen

Laut Polizei fiel dem Mieter am Donnerstag, dem 22. Oktober 2026, gegen 12.30 Uhr auf, dass das Vorhängeschloss an seinem Kellerabteil verschwunden war. Als er nachsah, fand er das Abteil voller Gegenstände, die nicht von ihm stammten. Er verständigte daraufhin die Polizei.

Die Beamten zogen die Tatortgruppe des Landeskriminalamts hinzu. Sichergestellt wurden mehrere E-Scooter und Fahrräder, rund 100 Akkus für E-Scooter sowie ein Moped ohne Kennzeichen. Die genaue Herkunft der Gegenstände ist noch Gegenstand der Ermittlungen.

## Verdächtiger wohnt im selben Haus

Im Zuge der Erhebungen geriet ein 45-jähriger Mann ins Visier der Ermittler, der laut Polizei im selben Gebäude wohnt. Er soll das fremde Kellerabteil über Monate hinweg genutzt haben, vor allem in den Nachtstunden. Dabei soll er immer wieder Gegenstände hinein- und hinausgebracht haben.

Der Mann wurde angezeigt. Die Ermittlungen dauern an, insbesondere zur Frage, woher die Fahrzeuge, Akkus und Geräte stammen und ob sie bestimmten Diebstählen zugeordnet werden können. Für den Verdächtigen gilt die Unschuldsvermutung.

## Diebesgut in Wien-Favoriten: Was Bestohlene jetzt tun können

Wer in Wien zuletzt ein E-Scooter, ein Fahrrad oder ein Moped als gestohlen gemeldet hat, kann sich bei der Polizei nach dem Stand der Ermittlungen erkundigen. Hilfreich ist es, folgende Unterlagen bereitzuhalten:

- die Anzeigebestätigung mit Aktenzahl
- Kaufbeleg oder Rechnung des Fahrzeugs
- Rahmen- oder Seriennummer, falls notiert
- Fotos, auf denen besondere Merkmale erkennbar sind

Bei Fahrrädern und E-Scootern erleichtert eine registrierte Rahmen- oder Seriennummer die Zuordnung sichergestellter Gegenstände erheblich. Wer diese Nummern noch nicht notiert hat, sollte das nachholen.

## Kellerabteile regelmäßig kontrollieren

Der Fall zeigt, dass Kellerabteile in Mehrparteienhäusern oft wochenlang unbeachtet bleiben. Wer sein Abteil nur selten aufsucht, bemerkt fremde Nutzung oder Einbruchsspuren unter Umständen erst spät. Einige einfache Maßnahmen helfen:

1. Das Abteil in regelmäßigen Abständen kontrollieren, auch wenn man nichts benötigt.
2. Ein stabiles Schloss verwenden und auf Beschädigungen achten.
3. Wertvolle Gegenstände wie Fahrräder oder Akkus möglichst nicht dauerhaft im Keller lagern.
4. Auffälligkeiten – fehlende Schlösser, aufgebrochene Türen, nächtliches Treiben – der Hausverwaltung und bei Verdacht der Polizei melden.

Fremde Gegenstände im eigenen Abteil sollte man nicht selbst wegräumen oder untersuchen, sondern die Polizei verständigen. So bleiben mögliche Spuren erhalten, und die Gegenstände können korrekt sichergestellt werden.

## Akkus richtig lagern

Bemerkenswert ist im aktuellen Fall die große Zahl an E-Scooter-Akkus. Lithium-Ionen-Akkus können bei Beschädigung oder unsachgemäßer Lagerung in Brand geraten. Feuerwehren raten generell davon ab, größere Mengen solcher Akkus in Kellern oder Stiegenhäusern aufzubewahren. Wer selbst Akkus für E-Scooter oder E-Bikes besitzt, sollte sie trocken, bei Raumtemperatur und fern von brennbarem Material lagern und nicht unbeaufsichtigt laden.

Die Polizei hat keine weiteren Details zur genauen Adresse des Wohnhauses im 10. Bezirk veröffentlicht. Hinweise zu dem Fall nimmt jede Polizeiinspektion entgegen.','chronik','Wien','wien','news','Presseinfo Redaktion','/assets/img/artikel/diebesgut-wien-favoriten-kellerabteil-e-scooter-akkus.webp','Landespolizeidirektion Wien','https://www.polizei.gv.at/wien/presse/aussendungen/presse1192.html?prid=364245376a482b48476e413d&pro=0','published','2026-10-24T04:50:00.000Z','2026-10-24T04:44:01.085Z','Diebesgut in Wien-Favoriten: Fund im Kellerabteil','Diebesgut in Wien-Favoriten: In einem fremden Kellerabteil fand die Polizei E-Scooter, Fahrräder und rund 100 Akkus. Alle Details zum Fall.','Diebesgut Wien-Favoriten','["Diebesgut Wien-Favoriten","Favoriten Polizei","Kellerabteil Diebesgut","E-Scooter gestohlen Wien","E-Scooter Akkus sichergestellt","Polizei Wien Favoriten Anzeige","gestohlenes Fahrrad Wien wiederfinden","Kellerabteil sichern Tipps"]','Diebesgut in Wien-Favoriten: E-Scooter und Akkus in einem Kellerabteil','Dim basement storage corridor of an old Viennese apartment building with wooden slatted cellar compartments, one compartment door open revealing several electric scooters, bicycles and stacked scooter batteries, flashlight beam, police evidence atmosphere, no people, no text, no logos, no readable signs','[{"q":"Was wurde im Kellerabteil in Wien-Favoriten gefunden?","a":"Laut Polizei mehrere E-Scooter und Fahrräder, rund 100 E-Scooter-Akkus, Elektrogeräte und ein Moped ohne Kennzeichen."},{"q":"Wer steht unter Verdacht?","a":"Ein 45-jähriger Bewohner desselben Hauses wurde angezeigt. Es gilt die Unschuldsvermutung, die Ermittlungen laufen."},{"q":"Was tun, wenn man fremde Gegenstände im eigenen Keller findet?","a":"Nichts verändern und die Polizei verständigen, damit Spuren gesichert und die Gegenstände zugeordnet werden können."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.ca